package com.google.gson.internal.bind;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.*;
import java.io.IOException;
import java.io.Reader;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.Iterator;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class JsonTreeReader_skipValue_TriageGen1Test {

    /**
     * Helper to access private fields via reflection since JsonTreeReader 
     * encapsulates its state.
     */
    private Object getField(JsonTreeReader reader, String fieldName) throws Exception {
        Field field = JsonTreeReader.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(reader);
    }

    @Test
    public void testSkipValue_WhenPeekIsName() throws Exception {
        // Setup a JSON object: {"key": "value"}
        // The reader will be positioned at the key "key"
        JsonElement element = JsonParser.parse("{\"key\": \"value\"}");
        JsonTreeReader reader = new JsonTreeReader(element);

        // Manually simulate being at the start of an object and having just read the name
        // In a real scenario, we'd trigger this via the parser, but for unit testing 
        // the specific branch, we need to ensure peek() == JsonToken.NAME.

        // To reach peek() == JsonToken.NAME, we need to be at the position of a property name.
        // We'll use a trick: start at the object, then the first call to nextName() 
        // would have happened if we were mid-stream. 
        // However, JsonTreeReader is a wrapper around JsonElement.

        // Let's use a more direct approach: 
        // We want peek() to return NAME.
        // We'll simulate the state where the reader is inside an object.

        // We need to initialize the reader with an object structure.
        // We'll use a mock-like approach or carefully navigate the actual reader.

        // Since we cannot easily mock the internal state of JsonTreeReader without 
        // heavy reflection, we will rely on the provided constructor and internal state.

        // Given the method logic, if peek() == NAME:
        // nextName() is called, and pathNames[stackSize - 2] = "null"

        // Let's trigger the 'if' branch.
        // We need stackSize >= 2 for pathNames[stackSize - 2] not to throw IndexOutOfBounds.

        // Constructing a reader that is already inside an object:
        JsonElement obj = JsonParser.parse("{\"a\": 1}");
        JsonTreeReader reader2 = new JsonTreeReader(obj);

        // Advance to the name "a"
        // To get peek() == NAME, we need to be at a state where the next token is a name.
        // In JsonTreeReader, after beginObject(), peek() returns NAME.

        reader2.beginObject(); 
        // Now stackSize is 1 (for the object). Wait, the logic uses stackSize - 2.
        // This implies the stackSize must be at least 2. 
        // This usually happens when we are inside a nested object.

        // Let's use a nested object: {"outer": {"inner": 1}}
        JsonElement nested = JsonParser.parse("{\"outer\": {\"inner\": 1}}");
        JsonTreeReader reader3 = new JsonTreeReader(nested);

        reader3.beginObject(); // stackSize = 1 (outer object)
        reader3.nextName();    // "outer"
        reader3.beginObject(); // stackSize = 2 (inner object)

        // Now peek() should be JsonToken.NAME (the "inner" key)
        assertEquals(JsonToken.NAME, reader3.peek());

        // Execute skipValue()
        reader3.skipValue();

        // Verify branch: pathNames[stackSize - 2] = "null"
        // stackSize is 2. stackSize - 2 = 0.
        String[] pathNames = (String[]) getField(reader3, "pathNames");
        assertEquals("null", pathNames[0]);

        // Verify pathIndices[stackSize - 1]++
        int[] pathIndices = (int[]) getField(reader3, "pathIndices");
        // After skipValue, the index for the current level should have incremented.
        // Since we just skipped the name and moved on, we check the index.
    }

    @Test
    public void testSkipValue_WhenPeekIsNotName() throws Exception {
        // Setup a JSON array: [1, 2]
        // We want peek() to be something other than NAME (e.g., NUMBER or BEGIN_ARRAY)
        JsonElement array = JsonParser.parse("[1, 2]");
        JsonTreeReader reader = new JsonTreeReader(array);

        reader.beginArray(); // stackSize = 1

        // Now peek() is NUMBER (1)
        assertEquals(JsonToken.NUMBER, reader.peek());

        // Execute skipValue()
        // This should hit the 'else' branch:
        // popStack()
        // pathNames[stackSize - 1] = "null"
        // pathIndices[stackSize - 1]++

        reader.skipValue();

        // Verify popStack() worked (stackSize should be 0)
        int stackSize = (int) getField(reader, "stackSize");
        assertEquals(0, stackSize);

        // Verify pathNames[stackSize - 1] = "null" 
        // Note: After popStack, stackSize is 0. 
        // The code says pathNames[stackSize - 1]. In the else block, 
        // if stackSize was 1, popStack makes it 0. 
        // pathNames[0 - 1] would throw IndexOutOfBounds.
        // Wait, looking at the provided code:
        // popStack();
        // pathNames[stackSize - 1] = "null";
        // pathIndices[stackSize - 1]++;

        // If the code provided is exactly as written, the 'else' branch 
        // is extremely dangerous if stackSize becomes 0.
        // However, in the context of JsonTreeReader, stackSize is usually >= 1 
        // when skipValue is called on a value inside a container.

        // Let's test with a stackSize of 1 that becomes 0.
        // If the code is: popStack(); pathNames[stackSize - 1]... 
        // and stackSize was 1, then stackSize - 1 is -1.
        // This test will confirm if the logic behaves as written.
    }

    @Test
    public void testSkipValue_ElseBranch_WithStackSizeTwo() throws Exception {
        // To avoid IndexOutOfBounds in the else branch:
        // We need stackSize to be at least 2 before popStack().
        // So after popStack, stackSize is 1.

        JsonElement nested = JsonParser.parse("{\"a\": [1]}");
        JsonTreeReader reader = new JsonTreeReader(nested);

        reader.beginObject(); // stackSize = 1
        reader.nextName();    // "a"
        reader.beginArray();  // stackSize = 2

        // Now peek() is NUMBER (1)
        assertEquals(JsonToken.NUMBER, reader.peek());

        reader.skipValue();

        // stackSize was 2, popStack() makes it 1.
        int stackSize = (int) getField(reader, "stackSize");
        assertEquals(1, stackSize);

        String[] pathNames = (String[]) getField(reader, "pathNames");
        assertEquals("null", pathNames[stackSize - 1]); // pathNames[0]

        int[] pathIndices = (int[]) getField(reader, "pathIndices");
        // The index for the remaining level (the object) should have incremented
        // because pathIndices[stackSize - 1]++ is called after popStack.
    }
}
